function demoRows(p=program){if(p==='B/T')return names.map((name,i)=>({id:'ex'+i,name,date,program:p,section:'S1',kind:'1RM',lbs:[225,155,205,135,245][i],demo:true,rank:i!==3}));return names.map((name,i)=>({id:'ex'+i,name,date,program:'WOD',section:'S2',kind:'세트별 횟수·칼로리',value:['12 / 21 / 10 / 19 / 8 / 18','9 / 16 / 8 / 15 / 7 / 15','11 / 20 / 10 / 18 / 9 / 17','8 / 14 / 7 / 13 / 6 / 12','14 / 23 / 12 / 21 / 11 / 20'][i],demo:true,rank:i!==3}));}
function resultValue(r){return r.lbs!=null?`${formatWeight(r.lbs)} <small>${state.unit}</small>`:esc(r.value)}
function resultTable(p=program,limit=20){const rows=state.records.filter(r=>r.date===date&&r.program===p&&(!resultSection||r.section===resultSection)).slice(0,limit);if(!rows.length)return '<div class="empty">아직 입력된 기록이 없어요.<br>운동 후 첫 기록을 남겨주세요.</div>';return `<table class="record-table"><thead><tr><th>회원</th><th>구간</th><th>기록</th><th>참여</th></tr></thead><tbody>${rows.map(r=>`<tr><td><span class="table-name"><span class="avatar">${esc(r.name.slice(0,1))}</span>${esc(r.name)}</span></td><td><span class="tag">${r.section}</span></td><td><span class="${r.lbs!=null?'record-score':''}" style="${r.lbs==null?'font-size:10px':''}">${resultValue(r)}</span></td><td><span class="mini-badge">${r.rank?'순위 ON':'순위 OFF'}</span>${r.name===state.name||coach?` <button class="link" data-edit-record="${r.id}">수정</button>`:''}</td></tr>`).join('')}</tbody></table>`;}
function home(){const s=selected(),day=date,p=program||(s?.type==='B/T'?'B/T':'WOD');program=p;const wd=workout(p,day),open=s?.type==='OPEN GYM',slots=schedule(date),visible=coach&&!memberPreview||isReleased(day,serverNow()),tomorrow=addDays(today(),1),tomorrowOpen=isReleased(tomorrow,serverNow()),attend=state.attendance.filter(d=>d.startsWith(today().slice(0,7))).length;const status=chosenSession?'선택한 수업':s?.current?'지금 진행 중':s?.ended?'오늘의 마지막 수업':s?'다가오는 수업':'오늘은 휴식';const desc=s?.current?'수업이 진행 중이에요':s?.ended?'오늘도 수고하셨어요':s&&date===today()?`${Math.max(0,minutes(s.time)-seoulNow())}분 후 시작`:dateLabel(date);const tabs=new Date(day+'T12:00:00+09:00').getUTCDay()===3&&!holidayState.dates[day]?['WOD']:['WOD','B/T'];return `${intro('오늘도, 나를 켜는 시간.',`${dateLabel(date)} · ${holidayState.dates[date]?holidayState.dates[date].name+(slots.length?' · 특별 수업 운영':' · 기본 휴강'):'함께 움직이고, 어제보다 한 걸음 더.'}`,datePicker())}${state.noticeOn?`<div class="notice"><span>${icon('bell')} NOTICE</span><div class="notice-track"><span class="notice-text">${esc(state.notice)}</span></div><button data-action="notice" aria-label="공지 자세히 보기">↗</button></div>`:''}<section class="panel tomorrow-card"><div><strong>${tomorrowOpen?'내일 운동이 공개됐어요.':'내일 운동은 '+releaseTime+'에 만나요.'}</strong><p>${dateLabel(tomorrow)} · 한국 시간 ${releaseTime} 공개</p></div><button class="btn ${tomorrowOpen?'primary':'soft'}" data-action="tomorrow" ${tomorrowOpen||coach&&!memberPreview?'':'disabled'}>${tomorrowOpen?'내일 운동 보기':coach&&!memberPreview?'운영자 미리 보기':releaseTime+' 공개'}</button></section><div class="dashboard"><section class="panel workout-panel"><div class="workout-hero"><div class="hero-top"><div class="status-pill"><i></i>${status}</div><span>${desc}</span></div><div class="hero-title"><div><div class="time">${s?.time||'REST'} ${s?`<span style="font-size:23px;color:#8db4ee">— ${s.end}</span>`:''}</div><p>${open?'나만의 페이스로, 자유롭게 운동하세요.':s?.type==='WOD'?'Work of the Day':s?'Body Training':'회복도 훈련의 일부입니다.'}</p></div><div class="hero-type">${open?'OPEN':s?.type||'OFF'}</div></div><div class="hero-bottom">${icon('pin')} ONOFF CROSSFIT · ILGWANG <span style="margin-left:auto">${open?'FREE TRAINING':s?'60 MIN TRAINING':'RECOVERY DAY'}</span></div></div><div class="workout-tabs"><div class="segmented">${tabs.map(t=>`<button data-program="${t}" class="${p===t?'active':''}">${t}</button>`).join('')}</div>${unitToggle()}</div><div class="workout-body">${visible?wd.sections.length?`${wd.overviewId?`<button class="video-link" data-video="${wd.overviewId}" data-video-title="오늘 운동 설명">▶ 오늘 운동 설명 보기</button>`:''}${wd.sections.map((sec,i)=>sectionCard(sec,i)).join('')}`:`<div class="empty">${slots.some(x=>x.type!=='OPEN GYM')?'수업 내용을 준비 중이에요.':'오늘은 정규 수업이 없어요.'}<br>${coach&&!memberPreview?'<button class="link" data-page="admin">수업 등록하러 가기 ↗</button>':`등록된 수업은 전날 ${releaseTime}에 공개됩니다.`}</div>`:'<div class="empty">아직 공개되지 않은 수업이에요.<br>해당 날짜 전날 ${releaseTime}에 공개됩니다.</div>'}</div><div class="workout-actions"><button class="btn soft" data-action="attendance">${icon(state.attendance.includes(today())?'check':'pin')}${state.attendance.includes(today())?'오늘 출석 완료':'출석하기'}</button><button class="btn primary" data-action="record" ${!visible||!wd.sections.some(x=>x.record)||date>today()?'disabled':''}>${icon('edit')}기록 입력</button></div></section><div class="right-column"><section class="panel"><div class="panel-head"><h2>${date===today()?'오늘의':dateLabel(date)} 타임테이블</h2>${icon('clock')}</div><div class="schedule">${slots.length?slots.map(x=>`<button class="schedule-row ${s?.time===x.time?'active':''}" data-session="${x.time}"><span class="sched-time">${x.time}</span><strong>${x.type==='OPEN GYM'?'오픈짐':x.type}</strong><small>${date===today()&&minutes(x.end)<=seoulNow()?'종료':s?.time===x.time?(s.current?'진행 중':'선택'):x.type==='OPEN GYM'?'자유':'60분'}</small></button>`).join(''):`<div class="empty">${holidayState.dates[date]?esc(holidayState.dates[date].name)+' · 기본 휴강':'오늘은 쉬어가는 날이에요.'}</div>`}</div><div class="schedule-foot">예약 없이 자유롭게 참여하세요.<span>평일 오픈짐 12:00–16:30 · 토요일 10:00–20:00</span></div></section><section class="panel attendance-card"><div class="small-label">꾸준함이 만드는 변화</div><h2 style="margin-top:6px">이번 달 나의 출석</h2><div class="att-number">${String(attend).padStart(2,'0')}<span>일 · 이번 달도 함께해요!</span></div><div class="progress"><div style="width:${Math.min(100,attend/20*100)}%"></div></div><div class="att-bottom"><span>한 번의 운동도 소중하게</span><button data-action="attendance-history">출석 달력 ↗</button></div></section></div></div><div class="lower-grid"><section class="panel"><div class="panel-head"><h2>함께 쌓는 운동 기록 <span class="tag">${p}</span></h2><button class="link" data-page="members">전체 보기 ${icon('arrow')}</button></div>${resultTable(p,3)}<div style="padding:9px 20px;font-size:9px;color:var(--muted)">운동 결과는 현재 기기의 미리보기 기록입니다.</div></section><section class="panel"><div class="panel-head"><h2>운동을 더 잘 이해하는 시간</h2></div><div class="settings-section"><p class="small-label">자세부터 기록까지, 동작별로 한곳에서 확인해요.</p><button class="btn soft" data-page="library">${icon('weight')} 운동 사전 열기</button></div></section></div>`;}
function members(){return `${intro('함께 쌓는 기록', '같은 운동, 각자의 도전. 서로의 움직임을 응원해요.',datePicker())}<div class="page-toolbar"><div class="filter-tabs">${['WOD','B/T'].map(p=>`<button class="${recordsFilter===p?'active':''}" data-records-filter="${p}">${p}</button>`).join('')}</div><button class="btn primary" data-action="record">${icon('plus')}${coach?'회원 기록 입력':'내 기록 입력'}</button></div><div class="preview-note">운동 결과는 현재 기기에만 저장되는 미리보기입니다. 순위 참여를 꺼도 기록은 공개되는 설정입니다.</div><section class="panel"><div class="panel-head"><h2>${dateLabel(date)} · ${recordsFilter}</h2>${unitToggle()}</div>${resultTable(recordsFilter)}</section><div class="panel calculator"><h3>조건이 같을 때만 공정하게</h3><p class="muted" style="font-size:12px;margin-bottom:0">중량·시간·횟수 등 기록 종류와 운동 조건이 같은 구간끼리 순위를 비교합니다. 현재 예시 인터벌 기록에는 등수를 표시하지 않습니다.</p></div>`}
const movements=['Front Squat','Back Squat','Deadlift','Clean','Clean & Jerk','Snatch','Power Snatch','Strict Press','Push Press','Split Jerk'];
function best(m){const rs=state.rms.filter(r=>r.movement===m);return rs.sort((a,b)=>b.lbs-a.lbs)[0]}
function rm(){return `${intro('나의 가장 강한 순간', '한 번의 도전, 하나의 새로운 기준. 동작별 1RM을 모아보세요.',`<button class="btn primary" data-action="rm-add">${icon('plus')}1RM 기록</button>`)}<div class="page-toolbar"><span class="small-label">PERSONAL RECORDS · ${state.rms.length}개의 도전</span>${unitToggle()}</div><div class="content-grid">${movements.map(m=>{const b=best(m);return `<section class="panel rm-card"><div class="rm-icon">${icon('weight')}</div><button class="icon-btn add-rm" data-rm="${m}" aria-label="${m} 기록 추가">${icon('plus')}</button><h3>${m}</h3><div class="rm-number">${b?formatWeight(b.lbs):'—'}<small>${state.unit}</small></div><div class="rm-date">${b?`${esc(b.date)} · 나의 최고 기록`:'첫 번째 기록을 남겨보세요.'}</div><div class="rm-bottom"><span class="tag">${b?'PERSONAL BEST':'YOUR NEXT CHALLENGE'}</span><button class="link" data-rm-history="${m}">기록 이력 ↗</button></div></section>`}).join('')}</div><section class="panel calculator"><div class="panel-head" style="padding:0 0 17px"><h2>나의 1RM으로 중량 계산</h2>${icon('weight')}</div><label class="field" style="margin-top:18px">기준 동작<select id="calc-movement">${movements.map(m=>`<option>${m}</option>`).join('')}</select></label><div id="calc-results"></div></section>`}
function calc(){let m=$('#calc-movement')?.value;if(!m)return;const b=best(m);$('#calc-results').innerHTML=b?`<div class="calculator-results">${[50,60,70,75,80,90].map(p=>`<div>${p}%<strong>${formatWeight(b.lbs*p/100)}</strong>${state.unit}</div>`).join('')}</div><p class="field-hint" style="margin:15px 0 0">환산값입니다. 실제 원판 구성에 맞춰 중량을 조정해주세요.</p>`:'<div class="empty">이 동작의 1RM을 먼저 등록해주세요.</div>'}
function attendanceCalendar(){return monthGrid(today().slice(0,7)+'-01',false);}
function myRecords(){return `${intro('어제보다 한 걸음 더', '꾸준히 쌓아온 나의 운동을 돌아보세요.')}<div class="stats-strip"><div class="panel stat-box"><span class="small-label">이번 달 출석</span><strong>${state.attendance.filter(d=>d.startsWith(today().slice(0,7))).length}<small>일</small></strong></div><div class="panel stat-box"><span class="small-label">나의 운동 기록</span><strong>${state.records.filter(r=>r.name===state.name).length}<small>개</small></strong></div><div class="panel stat-box"><span class="small-label">1RM 도전</span><strong>${state.rms.length}<small>회</small></strong></div></div><div class="page-toolbar"><div class="filter-tabs">${['운동 기록','출석 달력'].map(t=>`<button class="${myTab===t?'active':''}" data-mytab="${t}">${t}</button>`).join('')}</div>${myTab==='운동 기록'?`<button class="btn primary" data-action="record">${icon('plus')}기록 입력</button>`:''}</div><section class="panel settings-section">${myTab==='출석 달력'?`<h2>${today().slice(0,7).replace('-','년 ')}월</h2>${attendanceCalendar()}<p class="field-hint">체험 출석만 표시됩니다. GPS 출석은 체육관 위치 설정 후 사용할 수 있어요.</p>`:state.records.filter(r=>r.name===state.name).length?state.records.filter(r=>r.name===state.name).slice().reverse().map(r=>`<div class="history-row"><div>${esc(r.program)} · ${r.section}<small>${r.date} · ${esc(r.kind)}</small></div><div><strong>${resultValue(r)}</strong> <button class="link" data-edit-record="${r.id}">수정</button></div></div>`).join(''):'<div class="empty">아직 기록이 없어요.<br>첫 운동 기록을 남겨보세요.</div>'}</section>`}
function community(){const posts=allPosts().filter(p=>boardFilter==='전체'||p.category===boardFilter);return `${intro('우리 박스 이야기','공지부터 운동 번개까지, 온오프의 소식을 나눠요.',`<button class="btn primary" data-action="new-post">${icon('edit')}글쓰기</button>`)}<div class="page-toolbar"><div class="filter-tabs">${['전체','공지사항','운동 번개','공동구매','자유글'].map(t=>`<button class="${boardFilter===t?'active':''}" data-board-filter="${t}">${t}</button>`).join('')}</div><span class="small-label">${posts.length}개의 이야기</span></div><div class="board-list">${posts.map(p=>`<button class="panel post-card ${p.pinned?'pinned-post':''}" data-post="${p.id}"><span class="tag ${p.category==='공지사항'?'notice-tag':p.category==='공동구매'?'green':''}">${p.pinned?'📌 상단 고정 · ':''}${p.category}</span><h3>${esc(p.title)}</h3><p>${esc(p.body.split('\n')[0])}</p><div class="post-footer"><span>${esc(p.author)} · ${p.date}</span><span>${p.category==='공지사항'?'운영자 공지':`댓글 ${p.comments.length}`} ${icon('arrow')}</span></div></button>`).join('')||'<div class="panel empty">아직 등록된 글이 없어요.</div>'}</div>`;}
function settings(){return `${intro('나에게 맞는 온오프','프로필과 운동 환경을 설정해보세요.')}<div class="settings-grid"><section class="panel settings-section"><h2>회원 정보</h2><div class="setting-row"><div><strong>${esc(state.name)}</strong><p>${viewer?.role==='admin'?'운영자':viewer?.role==='coach'?'코치':'회원'} · ${viewer?.status==='approved'?'승인 완료':'승인 대기'}</p></div><button class="btn" data-action="name">이름 수정</button></div>${coach?`<div class="setting-row"><div><strong>운영 관리</strong><p>수업 등록·운동 영상${viewer.role==='admin'?'·회원 권한':''} 관리</p></div><button class="btn primary" data-page="admin">운영 메뉴 열기</button></div>`:''}<div class="setting-row"><div><strong>카카오 계정</strong><p>현재는 비공개 사이트 로그인으로 이용합니다.</p></div><button class="btn kakao" data-action="kakao">연결 안내</button></div><div class="setting-row"><div><strong>순위 참여</strong><p>끄면 내 기록은 공개되지만 순위에서는 제외돼요.</p></div><button class="switch ${state.rank?'on':''}" role="switch" aria-checked="${state.rank}" aria-label="순위 참여" data-action="rank"></button></div></section><section class="panel settings-section"><h2>운동 환경</h2><div class="setting-row"><div><strong>다크 모드</strong><p>온오프는 다크 모드로 제공됩니다.</p></div><span class="tag">DARK</span></div><div class="setting-row"><div><strong>기본 중량 단위</strong><p>단위를 바꿔도 같은 무게로 환산해요.</p></div>${unitToggle()}</div><div class="setting-row"><div><strong>운동 사전</strong><p>동작 설명 영상과 내 기록을 확인하세요.</p></div><button class="link" data-page="library">동작 찾아보기 ↗</button></div><div class="setting-row"><div><strong>현재 연결 상태</strong><p>수업·동작 영상·회원 권한은 서버에 저장됩니다.</p></div><button class="link" data-action="preview-info">자세히 ↗</button></div></section></div>`;}
function admin(){if(!coach)return `<section class="panel error-screen"><h2>운영 권한이 필요해요.</h2><p class="muted">운영자가 지정한 코치와 운영자만 이용할 수 있습니다.</p><button class="btn" data-page="home">홈으로</button></section>`;return `${intro('온오프의 하루를 준비하다.','한 번에 등록하고, 매일 '+releaseTime+'에 다음 날 운동을 공개하세요.')}<div class="page-toolbar"><span class="tag">${viewer.role==='admin'?'운영자':'코치'} 권한</span><button class="btn soft" data-action="member-preview">${memberPreview?'운영자 보기로 돌아가기':'회원 공개 화면 확인'}</button></div><div class="settings-grid"><section class="panel settings-section"><h2>엑셀로 수업 일괄 등록</h2><p class="field-hint" style="margin-top:12px">양식을 다운로드해 작성한 후 업로드하세요. 한 행에 한 구간을 입력합니다.</p><div class="excel-actions"><a class="btn soft" href="assets/onoff-workouts-template.xlsx?v=3" download>↓ 빈 양식 다운로드</a><a class="btn" href="assets/onoff-workouts-example.xlsx?v=3" download>예시 파일</a></div><div class="upload-zone"><label class="btn primary" for="excel-file">${icon('plus')}엑셀 파일 선택</label><input type="file" accept=".xlsx" id="excel-file" hidden><small>.xlsx · 최대 3MB / 1,000행<br>미리보기 확인 후 등록됩니다.</small></div></section><section class="panel settings-section"><h2>다음 날 운동 공개</h2><div class="public-time" style="margin-top:19px">${releaseTime} <span class="small-label">KST · 매일</span></div>${viewer.role==='admin'?`<form id="release-time-form"><label class="field">내일 운동 공개 시각<input name="releaseTime" type="time" required value="${releaseTime}"></label><p class="field-hint">아직 공개되지 않은 수업부터 적용합니다. 시각을 앞당기면 일부 수업은 즉시 공개될 수 있어요. 이미 공개된 수업은 유지됩니다.</p><button class="btn primary">공개 시각 저장</button></form>`:'<p class="field-hint">공개 시각은 운영자가 변경할 수 있어요.</p>'}<p class="field-hint">수업 날짜 전날 ${releaseTime}에 자동 공개됩니다.</p><div class="admin-summary"><span class="status-line"><i class="green-dot"></i>운영자·코치는 전체 수업 확인 가능</span><span class="status-line"><i class="green-dot"></i>지난 운동과 기록은 계속 확인 가능</span></div></section><section class="panel settings-section"><h2>대한민국 공휴일 달력</h2><p class="field-hint" style="margin-top:14px">공휴일·대체공휴일은 기본 휴강입니다. 해당 날짜에 운동 내용과 시작 시각을 등록하면 특별 수업으로 표시됩니다.</p><p class="field-hint">${esc(holidayState.source)} · ${holidayState.updatedAt?holidayState.updatedAt.slice(0,10):'저장된 일정'}</p><div class="admin-actions"><button class="btn soft" data-action="calendar">공휴일 달력 보기</button>${viewer.role==='admin'?'<button class="btn" data-action="sync-holidays">일정 새로고침</button>':''}</div></section><section class="panel settings-section"><h2>날짜별 수업 수정</h2><p class="field-hint" style="margin-top:12px">공개 전에도 수정할 수 있습니다.</p>${datePicker()}<div class="admin-actions" style="margin-top:18px"><button class="btn primary" data-edit-workout="WOD">WOD 등록·수정</button><button class="btn soft" data-edit-workout="B/T">B/T 등록·수정</button><button class="btn" data-action="record">회원 기록 입력</button></div><div class="history-row"><span>등록된 수업</span><strong>${Object.keys(state.workouts).length} <small>개</small></strong></div></section><section class="panel settings-section"><h2>운동 설명 영상</h2><p class="field-hint" style="margin-top:12px">운동 사전에 유튜브 주소를 한 번 등록하면, 관련 동작이 지정된 수업에 자동으로 연결됩니다.</p><button class="btn primary" data-page="library">운동 사전·영상 관리</button><div class="setting-row"><div><strong>공지 배너 노출</strong><p>현재 기기 미리보기 설정</p></div><button class="switch ${state.noticeOn?'on':''}" role="switch" aria-checked="${state.noticeOn}" aria-label="공지 배너 노출" data-action="notice-toggle"></button></div><button class="btn" data-action="edit-notice">공지 문구 수정</button></section>${viewer.role==='admin'?`<section class="panel settings-section member-manager" style="grid-column:1/-1"><h2>회원 승인·권한 관리</h2><p class="field-hint" style="margin-top:10px">접속한 계정이 여기에 표시됩니다. 회원·코치·운영자 권한을 지정할 수 있어요. 현재 사이트는 본인만 접속할 수 있는 비공개 상태입니다.</p>${state.members.map(m=>`<div class="setting-row"><div><strong>${esc(m.name)}</strong><p>${m.id===viewer.id?'내 계정 · ':''}${m.status==='approved'?'승인 완료':m.status==='pending'?'승인 대기':'이용 중지'}</p></div>${m.id===viewer.id?'<span class="tag">운영자</span>':`<div class="role-actions"><select class="role-select" aria-label="${esc(m.name)} 권한" id="role-${esc(m.id)}">${[['member','회원'],['coach','코치'],['admin','운영자']].map(([v,t])=>`<option value="${v}" ${m.role===v?'selected':''}>${t}</option>`).join('')}</select><select class="role-select" aria-label="${esc(m.name)} 승인 상태" id="status-${esc(m.id)}">${[['pending','승인 대기'],['approved','승인'],['suspended','이용 중지']].map(([v,t])=>`<option value="${v}" ${m.status===v?'selected':''}>${t}</option>`).join('')}</select><button class="btn primary" data-role-save="${esc(m.id)}">저장</button></div>`}</div>`).join('')}</section>`:''}</div><section class="panel settings-section" style="margin-top:24px"><h2>등록 일정</h2>${Object.values(state.workouts).sort((a,b)=>a.date.localeCompare(b.date)||a.program.localeCompare(b.program)).map(w=>`<div class="history-row"><div>${esc(w.date)} · ${w.program}<small>${isReleased(w.date,serverNow())?'회원 공개 중':addDays(w.date,-1)+' '+releaseTime+' 공개 예정'} · ${w.sections.length}개 구간</small></div><button class="link" data-workout-date="${w.date}" data-workout-program="${w.program}">수정 ↗</button></div>`).join('')||'<div class="empty">엑셀 파일로 첫 수업을 등록해보세요.</div>'}</section>`;}
function render(){if(!['home','members','records','rm','community','settings','admin','library'].includes(page))page='home';nav();if(loading){$('#main').innerHTML='<div class="skeleton">온오프의 하루를 불러오는 중…</div>';return}if(apiError){$('#main').innerHTML=`<section class="panel error-screen"><h2>연결을 확인해주세요.</h2><p>${esc(apiError)}</p><button class="btn primary" data-action="retry">다시 불러오기</button></section>`;return}if(viewer?.status!=='approved'){$('#main').innerHTML=`<section class="panel settings-section pending-wrap"><div class="eyebrow">ONOFF MEMBERS</div><h1>가입 승인 대기 중이에요.</h1><p class="muted">체육관에서 사용하는 실명을 입력해주세요.<br>관리자 승인 후 수업과 기록을 볼 수 있어요.</p><form id="profile-pending-form"><label class="field">실명<input name="name" required minlength="2" maxlength="30" value="${esc(state.name)}"></label><button class="btn primary">이름 저장</button></form></section>`;return}$('#main').innerHTML=(memberPreview?'<div class="member-preview">회원에게 공개된 화면을 확인 중입니다.<button data-action="member-preview">운영자로 돌아가기 ↗</button></div>':'')+({home,members,records:myRecords,rm,community,settings,admin,library:libraryPage}[page])();if(page==='rm')calc();}
function go(p){page=p;location.hash=p;render();window.scrollTo({top:0,behavior:'instant'})}
function modal(title,content){$('#modal-body').innerHTML=`<div class="modal-head"><h2>${title}</h2><button data-action="close" aria-label="닫기">×</button></div><div class="modal-content">${content}</div>`;if(!$('#modal').open)$('#modal').showModal();}
function close(){$('#modal-body').querySelectorAll('iframe').forEach(f=>f.remove());$('#modal').close()}
function themeIcon(){}
function setTheme(){document.documentElement.dataset.theme='dark';}
function rmForm(m='Front Squat'){modal('나의 1RM 기록',`<form id="rm-form"><label class="field">운동 동작<select name="movement">${movements.map(x=>`<option ${x===m?'selected':''}>${x}</option>`).join('')}</select></label><div class="field-row"><label class="field">성공 중량<input name="weight" type="number" min="0.1" max="3000" step="0.1" required placeholder="예: 185"></label><label class="field">단위<select name="unit"><option ${state.unit==='lbs'?'selected':''}>lbs</option><option ${state.unit==='kg'?'selected':''}>kg</option></select></label></div><label class="field">측정 날짜<input type="date" name="date" value="${date}" max="${today()}" required></label><p class="field-hint">실제 성공한 1회 최대 중량을 기록해주세요.</p><div class="form-footer"><button type="button" class="btn" data-action="close">취소</button><button class="btn primary">기록 저장</button></div></form>`)}
function recordForm(id){const existing=state.records.find(r=>r.id===id);let p=existing?.program||(page==='members'?recordsFilter:program)||'WOD';let d=existing?.date||(page==='home'?selected()?.date:date)||date;const w=workout(p,d);const secs=w.sections.map((s,i)=>({...s,index:i})).filter(s=>s.record);modal(coach?'회원 운동 기록 입력':'나의 운동 기록',`<form id="record-form" data-edit-id="${id||''}"><p class="field-hint">${d} · ${p} · 이 브라우저의 미리보기에 저장됩니다.</p>${coach?`<label class="field">회원 이름<input name="member" value="${esc(existing?.name||state.name)}" required maxlength="20"></label>`:''}<div class="field-row"><label class="field">운동 종류<select name="program" id="record-program"><option ${p==='WOD'?'selected':''}>WOD</option><option ${p==='B/T'?'selected':''}>B/T</option></select></label><label class="field">기록 구간<select name="section" id="record-section">${secs.map(s=>`<option value="${s.index}" ${existing?.section==='S'+(s.index+1)?'selected':''}>S${s.index+1} · ${esc(s.kind)}</option>`).join('')}</select></label></div><div id="record-fields"></div><label class="field">운동 날짜<input name="date" type="date" required value="${d}" max="${today()}"></label><label class="field">메모 (선택)<input name="note" maxlength="150" placeholder="사용한 중량, 변경 동작 등" value="${esc(existing?.note||'')}"></label><div class="form-footer"><button type="button" class="btn" data-action="close">취소</button><button class="btn primary" ${secs.length?'':'disabled'}>기록 저장</button></div></form>`);recordFields(existing)}
function recordFields(existing){const f=$('#record-form');if(!f)return;const p=f.elements.program.value;const w=workout(p,f.elements.date.value||date);const sec=w.sections[+f.elements.section.value];const isWeight=sec&&['중량','1RM'].includes(sec.kind);$('#record-fields').innerHTML=!sec?'<p>이 수업은 기록을 받지 않아요.</p>':isWeight?`<div class="field-row"><label class="field">${sec.kind==='1RM'?'1RM 성공 중량':'사용 중량'}<input name="weight" type="number" min="0.1" max="3000" step="0.1" required value="${existing?.lbs?formatWeight(existing.lbs):''}" placeholder="예: 135"></label><label class="field">단위<select name="unit"><option ${state.unit==='lbs'?'selected':''}>lbs</option><option ${state.unit==='kg'?'selected':''}>kg</option></select></label></div>${sec.kind==='1RM'?'<p class="field-hint">본인 기록은 내 1RM 탭에도 자동으로 연결돼요.</p>':''}`:`<label class="field">${esc(sec.kind)}<input name="value" required maxlength="120" placeholder="${sec.kind==='시간'?'예: 09:35':sec.kind==='세트별 횟수·칼로리'?'예: 12 / 21 / 10 / 19 / 8 / 18':'결과를 입력하세요'}" value="${esc(existing?.value||'')}"></label>${sec.kind==='세트별 횟수·칼로리'?'<p class="field-hint">1·3·5세트: 스내치 횟수 / 2·4·6세트: 로우 칼로리</p>':''}`;}
function postModal(id){const p=allPosts().find(x=>x.id===id);if(!p)return;if(p.serverNotice)return noticePostModal(p);modal(esc(p.category),`<h2 style="font-size:21px;line-height:1.6">${esc(p.title)}</h2><div class="board-meta">${esc(p.author)} · ${p.date}</div><div class="post-body">${esc(p.body)}</div>${p.category!=='자유글'?`<button class="btn ${p.joined.includes(state.name)?'soft':'primary'} full" data-join="${id}">${icon('check')}${p.joined.includes(state.name)?'참여 취소':'참여하기'} · ${p.joined.length}명</button><p class="field-hint">${p.joined.length?'참여자: '+p.joined.map(esc).join(', '):'함께할 첫 번째 회원이 되어보세요.'}</p>`:''}<h3 style="margin-top:25px">댓글 ${p.comments.length}</h3>${p.comments.map(c=>`<div class="comment"><small>${esc(c.author)}</small>${esc(c.text)}</div>`).join('')}<form id="comment-form" data-post-id="${id}"><label class="field">댓글 남기기<input name="text" maxlength="300" placeholder="따뜻한 한마디를 남겨주세요." required></label><button class="btn primary">댓글 등록</button></form>${p.author===state.name||coach?`<button class="link" data-delete-post="${id}" style="margin-top:22px;color:#cb5762">글 삭제</button>`:''}`)}
function workoutForm(p){if(!coach)return;const w=workout(p),sections=w.sections.length?w.sections:[{title:'',text:'',record:false,kind:'없음',movements:[]},{title:'',text:'',record:false,kind:'없음',movements:[]}];modal(`${p} 수업 등록 · ${date}`,`<form id="workout-form" data-program="${p}" data-count="${sections.length}"><p class="field-hint">공개 시각: ${addDays(date,-1)} ${releaseTime} · 저장하면 서버에 반영됩니다.</p>${sections.map((sec,i)=>editorSection(sec,i)).join('')}<div id="extra-sections"></div>${holidayState.dates[date]?`<label class="field" style="margin-top:20px">${esc(holidayState.dates[date].name)} 특별 수업 시작 시각<input name="sessions" required value="${esc((w.sessions||[]).join(', '))}" placeholder="예: 10:00, 11:00"></label><p class="field-hint">공휴일은 기본 휴강입니다. 수업을 진행할 시작 시각을 지정해주세요. 각 수업은 1시간입니다.</p>`:''}<button type="button" class="btn soft" data-action="add-section">${icon('plus')}구간 추가</button><label class="field" style="margin-top:22px">오늘 운동 설명 영상 (선택)<input type="url" name="overview" placeholder="https://youtu.be/…" value="${w.overviewId?'https://youtu.be/'+w.overviewId:''}"></label><div class="form-footer"><button class="btn primary">수업 저장</button></div></form>`);}
function showInfo(){modal('현재 연결 상태','<p><strong>서버에 저장되는 항목</strong><br>날짜별 수업, 운동 사전·영상, 로그인 계정의 승인·권한입니다. 수업은 운영자가 설정한 한국 시간에 공개됩니다.</p><p><strong>현재 기기에 저장되는 미리보기 항목</strong><br>운동 결과·1RM·게시판·공지 설정·체험 출석입니다. 이 항목은 아직 회원 간 공유되지 않습니다.</p><p><strong>추가 연결이 필요한 항목</strong><br>카카오 로그인과 GPS 출석입니다. 현재는 비공개 사이트 로그인으로 운영 화면을 확인할 수 있습니다.</p><button class="btn primary full" data-action="close">확인</button>');}
const actions={close,settings:()=>go('settings'),today:()=>{date=today();program=null;chosenSession=null;render()},'prev-date':()=>shiftDate(-1),'next-date':()=>shiftDate(1),record:()=>recordForm(),'rm-add':()=>rmForm(),rank:()=>{state.rank=!state.rank;state.records.filter(r=>r.name===state.name).forEach(r=>r.rank=state.rank);save();render();toast(state.rank?'순위 참여를 켰어요.':'순위 참여를 껐어요. 기록은 계속 공개돼요.')},notice:()=>{modal('ONOFF 공지사항',`<div class="post-body">${esc(state.notice)}</div><button class="btn primary full" data-action="close">확인</button>`)},'notice-toggle':()=>{if(!coach)return;state.noticeOn=!state.noticeOn;save();render()},'edit-notice':()=>{if(!coach)return;modal('공지 배너 문구',`<form id="notice-form"><label class="field">공지 내용<textarea name="notice" required maxlength="500">${esc(state.notice)}</textarea></label><button class="btn primary full">저장</button></form>`)},name:()=>modal('회원 이름 수정',`<form id="name-form"><label class="field">실명<input name="name" value="${esc(state.name)}" required maxlength="20" minlength="2"></label><button class="btn primary full">저장</button></form>`),kakao:()=>modal('카카오로 간편하게 시작',`<p>실서비스에서는 카카오 로그인 후 실명만 입력하면 가입을 신청할 수 있어요. 관리자 승인 후 체육관 앱을 이용합니다.</p><p class="field-hint">현재 카카오 개발자 앱이 연결되지 않아 실제 로그인·가입은 진행되지 않습니다.</p><button class="btn kakao full" disabled>카카오 로그인 · 연결 준비 중</button><button class="btn full" data-action="signup-preview">가입 신청 화면 체험</button>`),'signup-preview':()=>modal('회원 가입 신청 · 체험',`<form id="signup-form"><label class="field">체육관에서 사용하는 실명<input name="name" required minlength="2" maxlength="20" placeholder="이름을 입력해주세요"></label><p class="field-hint">실제 개인정보 수집 없이 화면 흐름을 확인하는 예시입니다. 승인된 회원에게 이름과 운동 기록이 공개되는 구조입니다.</p><label class="checkbox-label"><input type="checkbox" required>미리보기 가입 신청임을 확인했습니다.</label><button class="btn primary full">승인 신청 체험</button></form>`),'attendance-history':()=>{myTab='출석 달력';go('records')},attendance:()=>{if(state.attendance.includes(today()))return toast('오늘 출석을 이미 남겼어요.');modal('체육관 출석하기',`<p>체육관 도착 후 버튼을 누르면 현재 위치를 확인해 출석하는 방식입니다.</p><p><strong>체육관 위치가 아직 설정되지 않았어요.</strong><br>정확한 위치와 허용 반경을 설정한 후 GPS 출석을 사용할 수 있습니다.</p><p class="field-hint">현재는 위치 권한을 요청하지 않습니다. 아래 버튼은 이 브라우저에 체험 출석만 남깁니다.</p><button class="btn primary full" data-action="demo-attend">미리보기 출석 체험</button>`)},'demo-attend':()=>{if(!state.attendance.includes(today()))state.attendance.push(today());save();close();render();toast('체험 출석을 남겼어요. 실제 GPS 출석이 아닙니다.')},'new-post':()=>modal('우리 박스에 이야기 남기기',`<form id="post-form"><label class="field">말머리<select name="category"><option>운동 번개</option><option>공동구매</option><option>자유글</option></select></label><label class="field">제목<input name="title" required maxlength="80" placeholder="어떤 이야기를 나눌까요?"></label><label class="field">내용<textarea name="body" required maxlength="3000" placeholder="일시, 장소, 참여 방법 등을 적어주세요."></textarea></label><p class="field-hint">미리보기 글은 이 브라우저에만 저장됩니다.</p><button class="btn primary full">게시글 등록</button></form>`),'preview-info':showInfo};
function shiftDate(n){const target=addDays(date,n);if(!coach||memberPreview){if(!isReleased(target,serverNow()))return toast('해당 날짜 전날 '+releaseTime+'에 공개됩니다.')}const d=new Date(date+'T12:00:00+09:00');d.setUTCDate(d.getUTCDate()+n);date=d.toISOString().slice(0,10);program=null;chosenSession=null;render()}
document.addEventListener('click',e=>{let el=e.target.closest('button,a');if(!el)return;const d=el.dataset;if(d.noticeEdit){noticePostForm(d.noticeEdit);return}if(d.noticeDelete){confirmNoticeDelete(d.noticeDelete);return}if(d.noticeDeleteConfirm){deleteNotice(d.noticeDeleteConfirm);return}if(d.calendarDate){chooseCalendarDate(d.calendarDate);return}if(d.calendarShift){calendarMonth=addDays(calendarMonth,+d.calendarShift<0?-1:32).slice(0,7)+'-01';showCalendar();return}if(d.roleSave){updateRole(d.roleSave);return}if(d.movement){movementModal(d.movement);return}if(d.video){videoModal(d.video,d.videoTitle||'운동 설명');return}if(d.sectionRecord){recordForm();const select=$('#record-section');if(select){select.value=String(+d.sectionRecord-1);recordFields()}return}if(d.sectionHistory){sectionHistory(+d.sectionHistory-1);return}if(d.sectionResults){resultSection='S'+d.sectionResults;recordsFilter=program;go('members');return}if(d.workoutDate){date=d.workoutDate;workoutForm(d.workoutProgram);return}if(d.page)return go(d.page);if(d.action)return actions[d.action]?.();if(d.unit){state.unit=d.unit;save();return render()}if(d.program){program=d.program;return render()}if(d.session){const s=schedule(date).find(s=>s.time===d.session);chosenSession={...s,date,current:date===today()&&minutes(s.time)<=seoulNow()&&minutes(s.end)>seoulNow()};program=s.type==='B/T'?'B/T':'WOD';return render()}if(d.recordsFilter){recordsFilter=d.recordsFilter;resultSection=null;return render()}if(d.boardFilter){boardFilter=d.boardFilter;return render()}if(d.mytab){myTab=d.mytab;return render()}if(d.rm)return rmForm(d.rm);if(d.editRecord)return recordForm(d.editRecord);if(d.rmHistory){const rs=state.rms.filter(r=>r.movement===d.rmHistory).sort((a,b)=>b.date.localeCompare(a.date));return modal(esc(d.rmHistory)+' · 기록 이력',rs.length?rs.map(r=>`<div class="history-row"><span>${r.date}</span><strong>${formatWeight(r.lbs)} ${state.unit}</strong></div>`).join(''):'<div class="empty">아직 기록이 없어요.</div>')}if(d.post)return postModal(d.post);if(d.join){const p=state.posts.find(p=>p.id===d.join);p.joined=p.joined.includes(state.name)?p.joined.filter(n=>n!==state.name):[...p.joined,state.name];save();render();return postModal(p.id)}if(d.deletePost){const p=state.posts.find(p=>p.id===d.deletePost);if(!p||(!coach&&p.author!==state.name))return;modal('게시글 삭제',`<p>이 게시글과 댓글을 삭제할까요?</p><div class="form-footer"><button class="btn" data-post="${p.id}">돌아가기</button><button class="btn primary" data-confirm-delete="${p.id}">삭제하기</button></div>`);return}if(d.confirmDelete){state.posts=state.posts.filter(p=>p.id!==d.confirmDelete);save();close();render();return toast('게시글을 삭제했어요.')}if(d.editWorkout)return workoutForm(d.editWorkout);if(d.approve&&coach){const m=state.members.find(m=>m.id===d.approve);m.status='approved';save();render();toast(`${m.name}님의 체험 승인을 완료했어요.`)}});
document.addEventListener('change',async e=>{if(e.target.id==='excel-file'){await excelFile(e.target.files[0]);e.target.value='';return}if(e.target.id==='date-input'){if((!coach||memberPreview)&&!isReleased(e.target.value,serverNow())){toast('해당 날짜 전날 '+releaseTime+'에 공개됩니다.');e.target.value=date;return}date=e.target.value||today();program=null;chosenSession=null;render()}if(e.target.id==='calc-movement')calc();if(e.target.id==='record-program'){const f=$('#record-form'),w=workout(f.elements.program.value,f.elements.date.value||date);$('#record-section').innerHTML=w.sections.map((s,i)=>s.record?`<option value="${i}">S${i+1} · ${esc(s.kind)}</option>`:'').join('');recordFields()}if(e.target.id==='record-section')recordFields();if(e.target.matches('#record-form [name="date"]')){const f=$('#record-form'),w=workout(f.elements.program.value,e.target.value);$('#record-section').innerHTML=w.sections.map((s,i)=>s.record?`<option value="${i}">S${i+1} · ${esc(s.kind)}</option>`:'').join('');recordFields()}if(e.target.id==='library-search'){librarySearch=e.target.value;render()}});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target;if(!f.reportValidity())return;const data=Object.fromEntries(new FormData(f));const id=crypto.randomUUID();if(await serverForm(f,data))return;if(f.id==='rm-form'){state.rms.push({id,movement:data.movement,lbs:+data.weight*(data.unit==='kg'?2.2046226218:1),date:data.date});save();close();render();return toast('새로운 도전을 1RM에 기록했어요.')}if(f.id==='record-form'){const w=workout(data.program,data.date),s=w.sections[+data.section];if(!s?.record)return toast('이 구간은 기록을 받지 않아요.');const old=state.records.find(r=>r.id===f.dataset.editId);if(old&&!coach&&old.name!==state.name)return;const r={movement:s.movement||'',movements:s.movements||[],id:old?.id||id,name:coach?data.member.trim():state.name,date:data.date,program:data.program,section:'S'+(+data.section+1),kind:s.kind,rank:state.rank,note:data.note,writer:coach?'coach':'member'};if(data.weight)r.lbs=+data.weight*(data.unit==='kg'?2.2046226218:1);else r.value=data.value;if(!r.name||(!r.lbs&&!r.value?.trim()))return toast('기록 내용을 입력해주세요.');if(old)state.records[state.records.indexOf(old)]=r;else state.records.push(r);state.rms=state.rms.filter(x=>x.source!==r.id);if(s.kind==='1RM'&&r.name===state.name&&r.lbs)state.rms.push({id,source:r.id,movement:s.movement||'Front Squat',lbs:r.lbs,date:r.date});save();close();render();return toast('운동 기록을 저장했어요.')}if(f.id==='post-form'){if(!data.title.trim()||!data.body.trim())return;state.posts.unshift({id,category:data.category,title:data.title.trim(),body:data.body.trim(),author:state.name,date:today(),joined:[],comments:[]});save();close();render();return toast('새 이야기를 등록했어요.')}if(f.id==='comment-form'){if(!data.text.trim())return;const p=state.posts.find(p=>p.id===f.dataset.postId);p.comments.push({author:state.name,text:data.text.trim()});save();return postModal(p.id)}if(f.id==='notice-form'&&coach){if(!data.notice.trim())return;state.notice=data.notice.trim();save();close();render();return toast('공지 문구를 저장했어요.')}if(f.id==='signup-form'){state.members.push({id,name:data.name.trim(),status:'pending'});save();modal('가입 신청 완료 · 체험','<p>관리자가 회원 확인 후 승인하는 단계입니다.</p><p class="field-hint">실제 가입은 진행되지 않았어요. 코치 화면에서 체험 신청을 확인할 수 있습니다.</p><button class="btn primary full" data-action="close">확인</button>');return}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()}});
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1)||'home';if(p!==page){page=p;render()}});

function tick(){$('#live-clock').textContent=new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(serverNow())+' KST'}
setTheme();render();tick();loadServer();setInterval(()=>{tick();if(!$('#modal').open&&!document.hidden)loadServer(false)},30000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)loadServer(false)});

async function request(path,body){const opts=body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{};const res=await fetch(path,opts);let data;try{data=await res.json()}catch{throw new Error('서버 응답을 확인할 수 없어요. 잠시 후 다시 시도해주세요.')}if(!res.ok){const e=new Error(data.error||'요청을 처리하지 못했어요.');Object.assign(e,data,{status:res.status});throw e}return data;}
async function loadServer(showLoading=true){if(showLoading)loading=true;try{const data=await request('/api/bootstrap'+(memberPreview?'?view=member':''));releaseTime=data.releaseTime||'22:00';publishedDates=data.publishedDates||[];notices=data.notices||[];if(data.calendar)holidayState=data.calendar;viewer=data.viewer;serverOffset=Date.parse(data.serverNow)-Date.now();state.workouts=data.workouts||{};state.members=data.members||[];libraryState=data.library||[];state.name=viewer.name;coach=['admin','coach'].includes(viewer.role)&&viewer.status==='approved';apiError='';loading=false;render();nextReleaseRefresh();return data;}catch(e){loading=false;if(showLoading||!viewer){apiError=e.message;render()}else toast(e.message);return null}}
function sectionCard(sec,i){const ms=sec.movements?.length?sec.movements:sec.movement?[sec.movement]:[];return `<div class="workout-section"><div class="section-mark">S${i+1}</div><details class="section-details" open><summary class="section-heading"><h3>${esc(sec.title)}</h3>${sec.record?`<span class="mini-badge">${esc(sec.kind)} 기록</span>`:''}</summary><div class="exercise">${workoutText(sec.text)}</div><div>${ms.map(name=>{const m=libraryState.find(m=>m.name===name);return `<button class="video-link" data-movement="${esc(name)}">${m?.videoId?'▶':'↗'} ${esc(name)} ${m?.videoId?'동작 영상':'알아보기'}</button>`}).join('')}</div>${sec.record?`<div class="section-tools"><button data-section-history="${i+1}">${icon('clock')} 내 기록</button><button data-section-results="${i+1}">${icon('users')} 회원 결과</button><button class="log-result" data-section-record="${i+1}" ${date>today()?'disabled':''}>${icon('edit')} 기록 입력</button></div>`:''}</details></div>`;}
function libraryPage(){return `${intro('좋은 움직임의 시작','동작을 배우고, 내 기록을 확인해보세요.')}<div class="library-page-head"><input type="search" id="library-search" class="search-input" placeholder="동작 검색 · 예: Front Squat" aria-label="동작 검색" value="${esc(librarySearch)}">${coach?'<button class="btn primary" data-action="movement-add">'+icon('plus')+'동작 등록</button>':''}</div><div class="library-grid" id="library-cards">${libraryCards()}</div>`;}
function libraryCards(){return libraryState.filter(m=>m.name.toLowerCase().includes(librarySearch.toLowerCase())).map(m=>`<button class="panel movement-card" data-movement="${esc(m.name)}"><h3>${esc(m.name)}</h3><p>${m.videoId?'▶ 동작 설명 영상':'동작 설명 영상 준비 중'}${best(m.name)?' · 내 최고 '+formatWeight(best(m.name).lbs)+' '+state.unit:''}</p></button>`).join('')||'<div class="empty">검색 결과가 없어요.</div>';}
function movementModal(name){const m=libraryState.find(x=>x.name===name)||{name,notes:'',videoId:''},b=best(name);modal(esc(name),`${m.videoId?`<button class="btn primary full" data-video="${m.videoId}" data-video-title="${esc(name)}">▶ 동작 설명 영상 보기</button>`:'<div class="empty">운동 설명 영상을 준비 중이에요.</div>'}${m.notes?`<div class="post-body">${esc(m.notes)}</div>`:''}<div class="history-row"><span>나의 1RM</span><strong>${b?formatWeight(b.lbs)+' '+state.unit:'아직 기록이 없어요'}</strong></div><button class="btn soft full" data-rm-history="${esc(name)}">내 1RM 기록 이력</button>${coach?`<button class="btn full" data-movement-edit="${esc(name)}">영상·설명 수정</button>`:''}`);}
function videoModal(id,title){if(!/^[\w-]{11}$/.test(id))return;modal(esc(title),`<iframe class="video-frame" src="https://www.youtube-nocookie.com/embed/${id}" title="${esc(title)}" allow="accelerometer; clipboard-write; encrypted-media; gyroscope; picture-in-picture; fullscreen" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe><a class="btn full" href="https://www.youtube.com/watch?v=${id}" target="_blank" rel="noopener noreferrer">유튜브에서 보기 ↗</a><p class="field-hint">재생되지 않으면 유튜브에서 열어주세요.</p>`);}
function movementForm(name=''){if(!coach)return;const m=libraryState.find(x=>x.name===name)||{name,videoId:'',notes:''};modal(name?'운동 영상·설명 수정':'운동 동작 등록',`<form id="movement-form"><label class="field">동작 이름<input name="name" required maxlength="80" minlength="2" value="${esc(m.name)}" ${name?'readonly':''} placeholder="예: Front Squat"></label><label class="field">유튜브 영상 주소 (선택)<input name="url" type="url" value="${m.videoId?'https://youtu.be/'+m.videoId:''}" placeholder="https://youtu.be/…"></label><label class="field">동작 설명·코칭 포인트<textarea name="notes" maxlength="1000">${esc(m.notes)}</textarea></label><p class="field-hint">영상 없이 동작부터 등록해도 됩니다. 관련 동작이 지정된 모든 수업에 연결됩니다.</p><button class="btn primary full">저장</button></form>`);}
function sectionHistory(index){const sec=workout().sections[index];if(!sec)return;const ms=sec.movements?.length?sec.movements:sec.movement?[sec.movement]:[];const rows=state.records.filter(r=>r.name===state.name&&(ms.length?ms.some(m=>r.movement===m||r.movements?.includes(m)):r.program===program&&r.section==='S'+(index+1)));modal('나의 운동 기록',`<p class="field-hint">${ms.length?ms.map(esc).join(' · '):esc(sec.title)}</p>${rows.length?rows.slice().reverse().map(r=>`<div class="history-row"><div>${esc(r.date)}<small>${r.program} · ${r.section}</small></div><strong>${resultValue(r)}</strong></div>`).join(''):'<div class="empty">아직 남긴 기록이 없어요.</div>'}`);}
function editorSection(sec,i){return `<section class="record-form-section"><h3>S${i+1}</h3><label class="field">구간 제목<input name="title${i}" value="${esc(sec.title||'')}" required maxlength="100"></label><label class="field">운동 내용<textarea name="text${i}" required maxlength="5000">${esc(sec.text||'')}</textarea></label><label class="checkbox-label"><input type="checkbox" name="record${i}" ${sec.record?'checked':''}>이 구간 기록 받기</label><label class="field">기록 종류<select name="kind${i}">${KINDS.filter(k=>k!=='없음').map(k=>`<option ${sec.kind===k?'selected':''}>${k}</option>`).join('')}</select></label><label class="field">관련 동작 (여러 개는 ;로 구분)<input name="movements${i}" value="${esc((sec.movements?.length?sec.movements:sec.movement?[sec.movement]:[]).join('; '))}" placeholder="Front Squat; Row"></label><p class="field-hint">1RM은 동작을 하나 지정해주세요. 운동 사전에 등록된 이름을 사용합니다.</p></section>`;}
let xlsxReady;
async function loadXlsx(){if(window.XLSX)return window.XLSX;if(!xlsxReady)xlsxReady=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='assets/xlsx.full.min.js';script.onload=()=>resolve(window.XLSX);script.onerror=()=>{xlsxReady=null;script.remove();reject(new Error('엑셀 읽기 기능을 불러오지 못했어요. 다시 시도해주세요.'))};document.head.appendChild(script)});return xlsxReady;}
async function excelFile(file){if(!file)return;if(!coach)return toast('수업 관리 권한이 필요해요.');if(!file.name.toLowerCase().endsWith('.xlsx'))return toast('.xlsx 파일을 선택해주세요.');if(file.size>3*1024*1024)return toast('3MB 이하 파일을 선택해주세요.');modal('엑셀 파일 확인 중','<p>수업 내용과 날짜를 확인하고 있어요…</p>');try{const XLSX=await loadXlsx(),book=XLSX.read(await file.arrayBuffer(),{type:'array',cellDates:false});const sheet=book.Sheets['수업등록'];if(!sheet)throw new Error('수업등록 시트가 없어요. 제공된 양식을 사용해주세요.');const range=XLSX.utils.decode_range(sheet['!ref']||'A1');if(range.e.r>1000)throw new Error('최대 1,000행까지 등록할 수 있어요.');const head=XLSX.utils.sheet_to_json(sheet,{header:1,range:0,raw:false})[0]||[];const missing=HEADERS.slice(0,6).filter(h=>!head.includes(h));if(missing.length)throw new Error('필수 열이 없어요: '+missing.join(', '));const rows=XLSX.utils.sheet_to_json(sheet,{defval:'',raw:false,dateNF:'yyyy-mm-dd'});const validated=normalizeRows(rows,libraryState.map(m=>m.name),holidayState.dates);if(validated.errors.length){importWorkouts=[];return modal('엑셀 내용을 확인해주세요',`<div class="import-error">${validated.errors.slice(0,40).map(esc).join('<br>')}</div><p class="field-hint">아직 저장된 내용은 없습니다. 오류를 수정한 뒤 다시 올려주세요.</p><button class="btn full" data-action="close">닫기</button>`)}if(!validated.workouts.length)throw new Error('등록할 수업이 없어요. 수업등록 시트에 내용을 작성해주세요.');importWorkouts=validated.workouts;importPreview(file.name);}catch(e){importWorkouts=[];modal('파일을 확인해주세요',`<p>${esc(e.message)}</p><button class="btn full" data-action="close">확인</button>`);}}
function importPreview(filename='선택한 파일',serverCollisions=[]){const overlaps=serverCollisions.length?serverCollisions:importWorkouts.filter(w=>state.workouts[w.date+'_'+w.program]).map(w=>w.date+' '+w.program);modal('수업 일괄 등록 미리보기',`<p><strong>${esc(filename)}</strong><br>${importWorkouts.length}개 수업 · ${importWorkouts.reduce((a,w)=>a+w.sections.length,0)}개 구간</p><div class="upload-preview"><table class="import-table"><thead><tr><th>날짜</th><th>수업</th><th>구간</th><th>공개</th></tr></thead><tbody>${importWorkouts.map(w=>`<tr><td>${w.date}</td><td>${w.program}</td><td>${w.sections.length}개</td><td>${isReleased(w.date,serverNow())?'등록 즉시 공개':addDays(w.date,-1)+' '+releaseTime}</td></tr>`).join('')}</tbody></table></div>${overlaps.length?`<div class="import-error">기존 수업과 ${overlaps.length}개가 겹쳐요.<br>${overlaps.slice(0,8).map(esc).join('<br>')}</div><label class="checkbox-label"><input type="checkbox" id="overwrite-check">기존 수업 내용을 이 파일의 내용으로 덮어씁니다.</label>`:''}<p class="field-hint">저장 전입니다. 날짜와 수업 내용을 확인해주세요. 미래 수업은 전날 ${releaseTime}에 공개됩니다.</p><div class="form-footer"><button class="btn" data-action="close">취소</button><button class="btn primary" data-action="import-save">${importWorkouts.length}개 수업 등록</button></div>`);}
async function importSave(){if(!coach||!importWorkouts.length)return;const check=$('#overwrite-check');if(check&&!check.checked)return toast('기존 수업 덮어쓰기를 확인해주세요.');const button=$('[data-action="import-save"]');button.disabled=true;try{const result=await request('/api/workouts',{workouts:importWorkouts,overwrite:!!check?.checked});importWorkouts=[];await loadServer(false);close();toast(`${result.count}개 수업을 등록했어요. 전날 ${releaseTime}에 공개됩니다.`)}catch(e){if(e.status===409)return importPreview('선택한 파일',e.collisions);toast(e.errors?.[0]||e.message);button.disabled=false;}}
async function updateRole(id){if(viewer?.role!=='admin')return;const role=document.getElementById('role-'+id)?.value,status=document.getElementById('status-'+id)?.value;try{await request('/api/members',{id,role,status});await loadServer(false);toast('회원 권한을 저장했어요.')}catch(e){toast(e.message)}}
async function serverForm(f,data){if(await communitySettingsForm(f,data))return true;if(!['workout-form','movement-form','name-form','profile-pending-form'].includes(f.id))return false;const submit=f.querySelector('button:not([type="button"])');if(submit)submit.disabled=true;try{if(f.id==='workout-form'){if(!coach)return true;const sections=Array.from({length:+f.dataset.count},(_,i)=>({title:data['title'+i],text:data['text'+i],record:data['record'+i]==='on',kind:data['kind'+i],movements:(data['movements'+i]||'').split(';').map(v=>v.trim()).filter(Boolean)}));const overviewId=data.overview?youtubeId(data.overview):'';if(overviewId===null)throw new Error('유효한 유튜브 영상 주소를 입력해주세요.');const validated=validateWorkouts([{date,program:f.dataset.program,sections,overviewId,sessions:(data.sessions||'').split(',').map(v=>v.trim()).filter(Boolean)}],libraryState.map(m=>m.name),holidayState.dates);if(validated.errors.length)throw new Error(validated.errors[0]);await request('/api/workouts',{workouts:validated.workouts,overwrite:true});}else if(f.id==='movement-form'){await request('/api/movements',data);}else{const old=state.name;await request('/api/profile',{name:data.name});state.records.filter(r=>r.name===old).forEach(r=>r.name=data.name.trim());save();}await loadServer(false);close();toast('저장했어요.');}catch(e){toast(e.errors?.[0]||e.message);}finally{if(submit)submit.disabled=false}return true;}
Object.assign(actions,{'tomorrow':()=>{const d=addDays(today(),1);if(!coach||memberPreview){if(!isReleased(d,serverNow()))return toast('내일 운동은 '+releaseTime+'에 공개됩니다.')}date=d;program=null;chosenSession=null;go('home')},'member-preview':async()=>{if(!coach)return;memberPreview=!memberPreview;await loadServer(false);go(memberPreview?'home':'admin')},'retry':()=>loadServer(),'movement-add':()=>movementForm(),'import-save':importSave,'add-section':()=>{const f=$('#workout-form');if(!f)return;const n=+f.dataset.count;if(n>=99)return;$('#extra-sections').insertAdjacentHTML('beforeend',editorSection({},n));f.dataset.count=String(n+1);}});
document.addEventListener('click',e=>{const el=e.target.closest('button');if(el?.dataset.movementEdit)movementForm(el.dataset.movementEdit)});
document.addEventListener('input',e=>{if(e.target.id==='library-search'){librarySearch=e.target.value;$('#library-cards').innerHTML=libraryCards()}});
$('#modal').addEventListener('close',()=>{$('#modal-body').querySelectorAll('iframe').forEach(f=>f.remove());importWorkouts=[]});

function nextReleaseRefresh(){clearTimeout(releaseTimer);const next=releaseAt(addDays(today(),1));const target=+serverNow()<next?next:releaseAt(addDays(today(),2));releaseTimer=setTimeout(async()=>{if(!document.hidden&&!$('#modal').open)await loadServer(false);nextReleaseRefresh()},Math.max(1000,target-(+serverNow())+100));}

function allPosts(){return [...notices,...state.posts].sort((a,b)=>Number(!!b.pinned)-Number(!!a.pinned)||(b.created_at||b.date).localeCompare(a.created_at||a.date));}
function noticePostModal(p){modal('공지사항',`${p.pinned?'<span class="tag notice-tag">📌 상단 고정</span>':''}<h2 style="margin-top:13px">${esc(p.title)}</h2><div class="board-meta">${esc(p.author)} · ${p.date}</div><div class="post-body">${esc(p.body)}</div>${viewer?.role==='admin'?`<div class="form-footer"><button class="btn" data-notice-delete="${p.id}">삭제</button><button class="btn primary" data-notice-edit="${p.id}">수정·고정 설정</button></div>`:''}`);}
function noticePostForm(id){if(viewer?.role!=='admin')return;const p=notices.find(p=>p.id===id);if(!p)return;modal('공지사항 수정',`<form id="notice-post-form" data-notice-id="${p.id}"><label class="field">제목<input name="title" required maxlength="100" value="${esc(p.title)}"></label><label class="field">내용<textarea name="body" required maxlength="5000">${esc(p.body)}</textarea></label><label class="checkbox-label"><input name="pinned" type="checkbox" ${p.pinned?'checked':''}>커뮤니티 상단에 고정</label><button class="btn primary full">공지 저장</button></form>`);}
function confirmNoticeDelete(id){if(viewer?.role!=='admin')return;modal('공지사항 삭제','<p>이 공지사항을 삭제할까요?</p><div class="form-footer"><button class="btn" data-action="close">취소</button><button class="btn primary" data-notice-delete-confirm="'+esc(id)+'">삭제</button></div>');}
async function deleteNotice(id){try{await request('/api/notices',{id,action:'delete'});await loadServer(false);close();toast('공지를 삭제했어요.')}catch(e){toast(e.message)}}
async function communitySettingsForm(f,data){const noticeForm=f.id==='notice-post-form'||f.id==='post-form'&&data.category==='공지사항';if(!noticeForm&&f.id!=='release-time-form')return false;if(viewer?.role!=='admin'){toast('운영자 권한이 필요해요.');return true}const submit=f.querySelector('button:not([type="button"])');if(submit)submit.disabled=true;try{if(noticeForm)await request('/api/notices',{id:f.dataset.noticeId||undefined,title:data.title,body:data.body,pinned:data.pinned==='on'});else await request('/api/settings',{releaseTime:data.releaseTime});await loadServer(false);close();toast(noticeForm?'공지를 저장했어요.':'운동 공개 시각을 '+releaseTime+'로 변경했어요.');}catch(e){toast(e.message)}finally{if(submit)submit.disabled=false}return true;}
function monthGrid(month,interactive=true){const year=+month.slice(0,4),m=+month.slice(5,7),days=new Date(year,m,0).getDate(),offset=new Date(month+'T12:00:00+09:00').getUTCDay();return `<div class="calendar holiday-calendar">${['일','월','화','수','목','금','토'].map((d,i)=>`<span class="weekday ${i===0?'holiday-day':''}">${d}</span>`).join('')}${'<span></span>'.repeat(offset)}${Array.from({length:days},(_,i)=>{const d=month.slice(0,8)+String(i+1).padStart(2,'0'),h=holidayState.dates[d],cls=[h?'holiday-day':'',state.attendance.includes(d)?'attended':'',d===today()?'today':'',d===date?'selected-day':''].join(' '),body=`${i+1}${state.attendance.includes(d)?' ✓':''}${h?'<small>'+esc(h.name)+'</small>':''}`;return interactive?`<button class="${cls}" data-calendar-date="${d}" aria-label="${d}${h?' '+esc(h.name):''}">${body}</button>`:`<span class="${cls}">${body}</span>`}).join('')}</div>`;}
function showCalendar(){if(!calendarMonth)calendarMonth=date.slice(0,7)+'-01';modal('대한민국 공휴일 달력',`<div class="month-nav"><button class="btn" data-calendar-shift="-1" aria-label="이전 달">‹</button><strong>${calendarMonth.slice(0,4)}년 ${+calendarMonth.slice(5,7)}월</strong><button class="btn" data-calendar-shift="1" aria-label="다음 달">›</button></div>${monthGrid(calendarMonth)}<p class="field-hint">빨간 날짜는 공휴일·대체공휴일입니다. 기본 휴강이며 등록된 특별 수업이 있으면 표시됩니다.</p><p class="field-hint">${esc(holidayState.source)}${holidayState.fallback||holidayState.stale?' · 저장된 일정 사용 중':''}</p>`);}
function chooseCalendarDate(d){if((!coach||memberPreview)&&!isReleased(d,serverNow()))return toast('해당 날짜 운동은 전날 '+releaseTime+'에 공개됩니다.');date=d;chosenSession=null;program=null;close();render();}
Object.assign(actions,{'calendar':()=>{calendarMonth=date.slice(0,7)+'-01';showCalendar()},'sync-holidays':async()=>{try{const response=await request('/api/holidays/sync',{});holidayState=response.calendar;render();toast(holidayState.fallback||holidayState.stale?'최신 일정을 불러오지 못해 저장된 일정을 유지했어요.':'대한민국 공휴일 일정을 새로고침했어요.')}catch(e){toast(e.message)}},'new-post':()=>modal('우리 박스에 이야기 남기기',`<form id="post-form"><label class="field">말머리<select name="category" id="post-category">${viewer?.role==='admin'?'<option>공지사항</option>':''}<option>운동 번개</option><option>공동구매</option><option>자유글</option></select></label><label class="field">제목<input name="title" required maxlength="100"></label><label class="field">내용<textarea name="body" required maxlength="5000"></textarea></label>${viewer?.role==='admin'?'<label class="checkbox-label" id="post-pin-label"><input name="pinned" type="checkbox">커뮤니티 상단에 고정</label>':''}<p class="field-hint">공지사항은 운영자만 작성할 수 있고, 서버에 저장됩니다. 일반 게시글은 아직 현재 기기의 미리보기입니다.</p><button class="btn primary full">게시글 등록</button></form>`)});
document.addEventListener('change',e=>{if(e.target.id==='post-category'&&$('#post-pin-label')){$('#post-pin-label').hidden=e.target.value!=='공지사항';if(e.target.value!=='공지사항')$('#post-pin-label input').checked=false}});
